import google.cloud.storage


def load_raw_from_gcs(path):
    """Load analysis blobs from GCS and validate by hand."""
    client = google.cloud.storage.Client()
    raw = client.bucket("analysis").blob(path).download_as_bytes()
    if not isinstance(raw, bytes):
        raise ValueError("malformed blob")
    return raw


class RawEnvelopeCache:
    """Cache of unvalidated analysis envelopes."""

    def store(self, path, raw):
        self._blobs[path] = raw

import google.cloud.storage
from mozilla_nimbus_schemas.jetstream import SampleSizes, Statistics


def load_sizing_from_gcs(path):
    """Load population sizing through GCS and validate via the shared schema."""
    client = google.cloud.storage.Client()
    raw = client.bucket("analysis").blob(path).download_as_bytes()
    return SampleSizes.model_validate_json(raw)


def validate_statistics_blob(raw):
    """Validate a statistics blob against the shared schema."""
    return Statistics.model_validate_json(raw)
